	$(element).click(function() {
		var currentId = this.id;
		if($('#'+currentId).hasClass("icon-down-dir")) {
			$('#'+currentId).parent().siblings().slideUp();
			$('#'+currentId).addClass('icon-right-dir');
			$('#'+currentId).removeClass('icon-down-dir');
		} else {
			$('#'+currentId).parent().siblings().slideDown();
			$('#'+currentId).addClass('icon-down-dir');
			$('#'+currentId).removeClass('icon-right-dir');
		}
	});

