function cacheCurrentURL() {
	var urlString = document.URL;
	if(urlString.indexOf("index.jsp#/Home") !== -1 || urlString.indexOf("index.jsp#/Inventory") !== -1 || urlString.indexOf("index.jsp#/Alarms") !== -1 || urlString.indexOf("index.jsp#/Maps") !== -1 || urlString.indexOf("index.jsp#/Workflows") !== -1 || (urlString.indexOf("index.jsp#/FWACollImg") !== -1 && (window.OPM.isFWADE && window.OPM.isFWAServer))) {
		cachedGoBackURL =  urlString.substring(urlString.indexOf("index.jsp#")+10);
	}
	// console.log("URL : " + cachedGoBackURL);
}

//window height & width
function WindowHtWd(){
	wHt=$(window).height();
	wWd=$(window).width();
}

//main nav height
function MainNavHt(){
	setTimeout(function(){
		MainNavHtVar=wHt-$('#ProductSettings').outerHeight()-$('#header').outerHeight();
		$('#MainNav').css({height:MainNavHtVar});
	},300);
}

//main nav custom scroll
function MainNavScroll(){
	$('#MainNav').mCustomScrollbar({
		axis:'y',scrollButtons:{enable:true},theme:'light-thick',scrollbarPosition:'outside'//No I18N
	});
}

function HorizontalViewMainNavScroll(){
	var horizontalMainNavLiWidth = 0;
	$('#MainNav .NavUl > li').each(function() {
	  horizontalMainNavLiWidth += $(this).outerWidth();
	});
	horizontalMainNavLiWidth=horizontalMainNavLiWidth+80;
	var horizontalMainNavWd=$('#MainNav .NavUl').outerWidth();
	if(horizontalMainNavWd < horizontalMainNavLiWidth){ horizontalMainNavLiWidth=horizontalMainNavLiWidth+300;}
	$('#MainNav .NavUl').css({width : horizontalMainNavLiWidth});
	$("#MainNav").mCustomScrollbar({
	  axis:"x",//No I18N
	  scrollButtons:{enable:true},
	  theme:"light-thick",//No I18N
	  scrollbarPosition:"outside"//No I18N
	});
	Ember.run.schedule("afterRender", function() {//No I18N
		$($("#MainNav .mCSB_container")[0]).css({"left": 0}); //left property getting set intermittently. Hence force applying the property.
		$("#MainNav").mCustomScrollbar('scrollTo','left',{scrollInertia:0});//No I18N
	});
}

//main nav custom scroll active or disabled
function NavScrollActive(){
	if($('#MainNav #mCSB_1_scrollbar_vertical').css('display')=='block'){
		$('body').removeClass('MainNavScroll-disabled');
		$('body').addClass('MainNavScroll-active');
		$('#MainNav .MainNavShadow').remove();
		$('#MainNav').append("<div class='MainNavShadow top'></div><div class='MainNavShadow bottom'></div>");
	}else{
		$('body').removeClass('MainNavScroll-active');
		$('body').addClass('MainNavScroll-disabled');
		$('#MainNav .MainNavShadow').remove();
	}
}

//product details - product accordion container height
function ProAccConHt(){
	SecPos=$('#ProductDetails .ProAccordionContainer');
	OffSet=SecPos.offset();
	if(OffSet !== undefined && OffSet.top !== undefined)
	{
		PosY=OffSet.top;
		ProAccConHt=wHt-PosY;
		SecPos.css({height:ProAccConHt});
	}
	if($('#wrapper').length > 0){
		productDetails=$('#wrapper').offset().left+$('#wrapper').outerWidth();
		$('li.PDTNav').removeClass('active').find('.PDTContainer').removeClass('active').css({width:'0',left:productDetails});//No I18N
	}
	
	$('body').removeClass('quickLinksOverlay');	
	//For Register Accordion
	$('.regAccr .regAccrHdr').click(function(){
		if($(this).parent().hasClass('active')){
			$(this).parent().removeClass('active');
			$(this).parent().find('.regAccrCont').slideUp();
		}else{
			$(this).parent().addClass('active');
			$(this).parent().find('.regAccrCont').slideDown();
		}
	});

}

//product accordion
function ProAccord(){
	$('.ProAccordion ul li.about').click(function(){
		if(!$(this).hasClass('active')){
			$(this).parent().find('li').removeClass('active');
			$(this).addClass('active');
			$('.ProAccordionContainer div.about').addClass('active').css({left:'0'});
			$('.ProAccordionContainer div.register').css({left:'200%'});
			$('.ProAccordionContainer div.register').hide();
			$('.ProAccordionContainer div.about').show();
		}
		if(!$(this).hasClass('dataAdded'))
		{
			//$(this).addClass('dataAdded')
			opm_getAboutDetails();
		}
	});

	$('.ProAccordion ul li.register').click(function(){
		if(!$(this).hasClass('active')){
			$(this).parent().find('li').removeClass('active');
			$(this).addClass('active');
			$('#licenseFile').val('');//No I18N
			$('.ProAccordionContainer div.about').hide();
 			$('#licenseFile').closest('.fileUpload').find('.fileUploadTxt').text('');//No I18N
			$('.ProAccordionContainer div.about').css({left:'-200%'});
			$('.ProAccordionContainer div.register').addClass('active').css({left:'0'});
			$('.ProAccordionContainer div.register').show();
		}
	});
}



