//All alarms menu list
function opm_selectAlarmMenu(thiss) 
{
	initAlarmListFilters();
	if($(thiss).hasClass('AllAlarms'))
	{
		redirectToAlarmList('All');//No I18N
	}
	else if($(thiss).hasClass('ActiveAlarms'))
	{
		redirectToAlarmList('Active');//No I18N
	}
	else if($(thiss).hasClass('EventLogAlarms'))
	{
		redirectToAlarmList('EventLog');//No I18N
	}
	else if($(thiss).hasClass('SysLogAlarms'))
	{
		redirectToAlarmList('SysLog');	//No I18N
	}
	else if($(thiss).hasClass('TrapAlarms'))
	{	
		redirectToAlarmList('Trap');//No I18N
	}
	else if($(thiss).hasClass('NFAAlarms'))
	{	
		redirectToAlarmList('NFA');//No I18N
	}
	else if($(thiss).hasClass('NCMAlarms'))
	{	
		redirectToAlarmList('NCM');//No I18N
	}
	else if($(thiss).hasClass('FWAAlarms'))
	{	
		redirectToAlarmList('FWA');//No I18N
	}
	else if($(thiss).hasClass('WebAlarms'))
	{	
		redirectToAlarmList('Web');//No I18N
	}
	else if($(thiss).hasClass('StorageAlarms')) {
		redirectToAlarmList('Storage');//No I18N
	}
	$('.FilterTypeHolder .timeFilterList ul li').removeClass("active");
	$('.FilterTypeHolder .timeFilterList ul li[data-value="all"]').addClass("active");
}

var donutArr = [];
//alarm filter severity
function AlrmFilterSeverity(severityArr,colors,title){
		$("#MainSeverityChart-A").data().nodata = false;
		if(!opm_setDummayDataDonut(severityArr))
		{
			severityArr = [{title:Ember.I18n.t('webclient.dials.nodata',this),value:1}];//No I18N
			title = Ember.I18n.t('webclient.dials.nodata',this);//No I18N
			colors = ["#7f7f7f"]//No I18N
			$("#MainSeverityChart-A").data().nodata = true;//No I18N
		}

		$("#MainSeverityChart-A").empty();
		donutArr = [];
		var donut = Morris.Donut({
		    element: 'MainSeverityChart-A',//No I18N
		    data: severityArr,
		    colors:colors,
		    labelTxt:title,
		    formatter: function (x) { return x}
		  }).on('click', function(i, row){//No I18N
            if(!$('.alarmInventoryFilterToggle').hasClass('active'))
            {
		  	if(row.value > 0)
			{
			  var s = donut.segments[i];
			  var filterObj = OPMClient.AlarmDetailsController.alarmFilterObj;
			  	filterObj.loadDialChart = false; 
				var ids = ['CatCritical-A','CatTrouble-A','CatAttention-A','CatServiceDown-A','CatInfo-A'];//No I18N

			  if(selectedSegments.length > 0)
	          {
	           
           		var indx = opm_objectFindByKey(selectedSegments,'index',s.index);//No I18N
            	if(indx === null && !filterObj.severity.includes(row.status))
            	{
                    if(row.status == 5){
                        $('#BarHolderClear').addClass("selected");
                    } else{
                        $("#"+ids[parseInt(row.status)-1]).addClass("active");
                    }
            		s.select();
               		selectedSegments.push(s);
               		filterObj.severity.push(row.status);
               	}
               	else{
                    if(row.status == 5){
                        $('#BarHolderClear').removeClass("selected");
                    } else{
                        $("#"+ids[parseInt(row.status)-1]).removeClass("active");
                    }
               		s.deselect();
               		selectedSegments.splice(indx,1);
               		var _arr = filterObj.severity;
               		_arr.splice( $.inArray(row.status, _arr), 1 );
               		if(selectedSegments.length === 0 && filterObj.category.length == 0 && filterObj.customFilter.length == 0 && filterObj.group.length == 0 && filterObj.bv.length == 0)
               		{
               			filterObj.severity = [];
               			// filterObj.category = [];
               			$('#BarHolderDiv').removeClass("selected");
               			if(OPMClient.AlarmDetailsController.currentPage === "Events")
				 	 	{
				 	 		OPMClient.AlarmDetailsController.alarmFilterObj.loadEventBarChart = true;
				 	 		OPMClient.Alarms.listEvents('Events','Events');//No I18N
				 	 	}
				 	 	else
				 	 	{
				 	 		filterObj.loadAlarmBarChart = true;
                            filterObj.loadDonutDialChart = filterObj.loadDialChart = true;
				 	 		loadAlarmsListIntoGrid();
				 	 		return;
				 	 	}
               		}
               	}
	          }
	          else
	          {
				if(row.status == 5){
					$('#BarHolderClear').addClass("selected");
				} else{
					$("#"+ids[parseInt(row.status)-1]).addClass("active");
				}
	          	filterObj.severity.push(row.status);
	            s.select();
	            selectedSegments.push(s);
	            
	          }
	         filterObj.loadAlarmBarChart = true;
	         $('.severityDonutChart .CatChart').empty();
	         if(window.OPM.currentView.name.split('.index')[0] !== 'Alarms.Alarm.'+OPMClient.AlarmDetailsController.currentPage)
		 	 {
		 		redirectToAlarmList(OPMClient.AlarmDetailsController.currentPage); 
		 	 }
		 	 else
		 	 {
		 	 	
		 	 	if(OPMClient.AlarmDetailsController.currentPage === "Events")
		 	 	{
		 	 		OPMClient.AlarmDetailsController.alarmFilterObj.loadEventBarChart = true;
		 	 		OPMClient.Alarms.listEvents('Events','Events',true);//No I18N
		 	 	}
		 	 	else
		 	 	{
		 	 		loadAlarmsListIntoGrid();
		 	 	}
		 	 }
		 	}
		  }
	});
    donutArr.push(donut);
}

//alarm filter by category
function AlrmFilterCategory(severityArr,colors,title){
		donutArr = [];

		$("#MainSeverityChart-A").data().nodata = false;
		if(!opm_setDummayDataDonut(severityArr))
		{
			severityArr = [{title:Ember.I18n.t('webclient.dials.nodata',this),value:1}];//No I18N
			title = Ember.I18n.t("webclient.dials.nodata");//No I18N
			colors = ["#7f7f7f"]//No I18N
			$("#MainSeverityChart-A").data().nodata = true;//No I18N
		}


		$("#MainSeverityChart-A").empty();
		var donut = Morris.Donut({
		    element: 'MainSeverityChart-A',//No I18N
		    data: severityArr,
		    colors:colors,
		    labelTxt:title,
		    formatter: function (x) { return x}
		  }).on('click', function(i, row){//No I18N
		  	if(row.value > 0)
			{
			  var s = donut.segments[i];
			   var filterObj = OPMClient.AlarmDetailsController.alarmFilterObj;
			  	filterObj.loadDialChart = false;
			  	filterObj.loadCategoryDial = false;

			  if(selectedSegments.length > 0)
	          {
	           
           		var indx = opm_objectFindByKey(selectedSegments,'index',s.index);//No I18N
            	if(indx === null)
            	{
            		s.select();
               		selectedSegments.push(s);
               		filterObj.category.push(row.title);
               		filterObj.categoryVal.push(row.category);
               	}
               	else{
               		s.deselect();
               		selectedSegments.splice(indx,1);
               		var _arr = filterObj.category;
               		var _arr2 = filterObj.categoryVal;
               		_arr.splice( $.inArray(row.title, _arr), 1 );
               		_arr2.splice( $.inArray(row.category, _arr2), 1 );
               		if(selectedSegments.length === 0)
               		{
               			filterObj.category = [];
               			filterObj.categoryVal = [];
               			//filterObj.severity = [];
               			loadAlarmsListIntoGrid();
               			return;
               		}
               	}
	          }
	          else
	          {
	          	OPMClient.AlarmDetailsController.alarmFilterObj.categoryVal = [];
	          	OPMClient.AlarmDetailsController.alarmFilterObj.category.push(row.title);
	          	OPMClient.AlarmDetailsController.alarmFilterObj.categoryVal.push(row.category);
	            s.select();
	            selectedSegments.push(s);
	            
	          }

	         filterObj.loadDonutDialChart = true;
	         if(window.OPM.currentView.name.split('.index')[0] !== 'Alarms.Alarm.'+OPMClient.AlarmDetailsController.currentPage)
		 	 {
		 		redirectToAlarmList(OPMClient.AlarmDetailsController.currentPage); 
		 	 }
		 	 else
		 	 {
		 	 	loadAlarmsListIntoGrid();
		 	 	
		 	 }
		 	}
		  });
	donutArr.push(donut);
}

