//Urls filter by Severity
function urlsFilterDial(id,categoryArr,colors,title){
		donutArr = [];
		selectedSegments = [];
		$("#"+id).data().nodata = false;//No I18N
		if(!opm_setDummayDataDonut(categoryArr))
		{
			categoryArr = [{title:'No Data',value:1}];//No I18N
			title = "No Data";//No I18N
			colors = ["#7f7f7f"]//No I18N
			$("#"+id).data().nodata = true;//No I18N
		}
		
		$("#"+id).empty();
		var donut = Morris.Donut({
		    element: id,//No I18N
		    data: categoryArr,
		    colors:colors,
		    labelTxt:title,
		    formatter: function (x) { return x}
		  }).on('click', function(i, row){//No I18N
			  var s = donut.segments[i];
			  if(row.value > 0)
			  {
				  var urlFilterObj = OPMClient.InventoryDeviceDetailsController.urlsFilterObj;
					if(JSON.parse(localStorage.getItem('urlsFilterObj'))!==null) {
						urlFilterObj = JSON.parse(localStorage.getItem('urlsFilterObj')); //No I18N
					}

				 urlFilterObj.isDial = false;
				  urlFilterObj.isHBar = true;
				  if(selectedSegments.length > 0)
		          {
		           
	           		var indx = opm_objectFindByKey(selectedSegments,'index',s.index);//No I18N
	            	if(indx === null)
	            	{
	            		s.select();	
	               		selectedSegments.push(s);
	               		urlFilterObj.severity.push(row.status);
	               	}
	               	else{
	               		s.deselect();
	               		selectedSegments.splice(indx,1);
	               		var _arr = urlFilterObj.severity;
	               		_arr.splice( $.inArray(row.status, _arr), 1 );
	               	}
		          }
		          else
		          {
		          	urlFilterObj.severity.push(row.status);
		            s.select();
		            selectedSegments.push(s);
		            
		          }
		          localStorage.setItem('urlsFilterObj',JSON.stringify(urlFilterObj)); //No I18N

		         opm_listUrls();
		     }
		  });
	donutArr.push(donut);
}


