//alarm if any one input is checked in the row - display common options
function AlarmListCommonOptions(alarmCategory){
	$('#AlarmList .multipleAlarms .ping.deviceSnpMultiPing').hide();//No I18N
		ChkInput=$('#opm_Alarms tr > td:first-child input[type=checkbox]:checked');
		OPMClient.AlarmOptionsController.set('isMultipleAlarmSelected',false);//No I18N

		var recCount = jQuery("#opm_Alarms").jqGrid('getGridParam', 'records');//No I18N
		var eventType = "";
		
		var alarmtitle = $('.alarm .FilterByList .FilterBy.active').html();
		if(window.OPM.oldView){
			//Alarm Tabs format changed hence alarm Titles handled.
			// alarmtitle = $(".opmInventoryNavList li.active").text();
			alarmtitle = $('#alarmTabsList .list li a.active').text();
		}
		if(alarmtitle === undefined || alarmtitle===""){
			//fix for oputils alarms title
			alarmtitle=Ember.I18n.t("widget.name.allalarm",this);//NO I18N
		}


		//fix for nfa, ncm & fwa alarm titles
		var alertType = OPMClient.AlarmDetailsController.alarmFilterObj.alertType;
		switch (alertType) {
			case "NFAAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.snapshot.flowanalysis",this); //No I18N
				break;
			case "NCMAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.snapshot.configmanagement",this); //No I18N
				break;
			case "FWAAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.tabname.FirewallAlarms",this); //No I18N
				break;
			case "All"://No I18N
				alarmtitle = Ember.I18n.t("widget.name.allalarm",this);//NO I18N
				break;
			case "ActiveAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.tab.activealarm",this);//NO I18N
				break;
			case "EventLogAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.tabname.EventLogAlarms",this);//NO I18N
				break;
			case "SyslogAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.Syslog",this);//NO I18N
				break;
			case "TrapAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.notification.snmptraps",this);//NO I18N
				break;
			case "WebAlarms"://No I18N
				alarmtitle = Ember.I18n.t("widget.name.webalarms",this);//NO I18N
				break;
			case "StorageAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.tab.opstor",this);//NO I18N
				break;
			case "CorrelatedAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclicent.ap.correlated.alarms",this);//NO I18N
				break;
			case "APMAlarms"://No I18N
				alarmtitle = Ember.I18n.t("webclient.snapshot.application",this);//NO I18N
				break;
			case "Problems"://No I18N
				alarmtitle = Ember.I18n.t("opstor.inventory.centera.node.problems",this);//NO I18N
				break;	
		}
		/*Custom View Names to Set as Custom View Alarms Title*/
		if(OPMClient.AlarmDetailsController.get("isCustomAlarm")) {
			var customPath = OPMClient.AlarmDetailsController.get("customPath");
			$.each(OPMClient.MenuController.CustomViews, function (index, value) {
				if(value.viewId!==undefined && value.viewId==customPath) {
					alarmtitle = value.displayName;
					$('#alarmTiltleTxt').attr('title',alarmtitle);
					if(alarmtitle!=null && alarmtitle.length >35)
					{
						alarmtitle = (alarmtitle.substring(0,35)+"...");//No I18N
					}
				}
			});
		}

		if(OPMClient.AlarmDetailsController.isProblemsList){
			alarmtitle = Ember.I18n.t("opstor.inventory.centera.node.problems",this);//NO I18N
		}

		if (ChkInput.length===0){
			$('#AlarmList').removeClass('AETIDRowChecked');
			$(".Options.multipleAlarms.actions").hide();
			Ember.run.schedule("afterRender", function() {//No I18N
				$(".viewType.opm_alarmView").show();
				$(".OpMToolBar").remove();
			});
			$("#alarmTiltleTxt").html(alarmtitle+" ("+recCount+")");//No I18N
		}else{
			$('#AlarmList').addClass('AETIDRowChecked').removeClass('alarmShortSummaryActive');
			$(".Options.multipleAlarms.actions").show();
			Ember.run.schedule("afterRender", function() {//No I18N
				$(".viewType.opm_alarmView").hide();
			});
			$('#opm_Alarms tr').removeClass('active');
			$("#alarmTiltleTxt").html(alarmtitle+" ("+ChkInput.length+" / "+recCount+")"); //No I18N

			if(ChkInput.length > 1 && (OPMClient.ApplicationController.isMSPCentralSelected || OPMClient.ApplicationController.isMSPAllProbeSelected) && window.OPM.isMSPCentral)
			{
				$('#AlarmList .multipleAlarms .ping,#AlarmList .multipleAlarms .clear').hide();
				$('#AlarmList .multipleAlarms .ping,#AlarmList .multipleAlarms .delete').hide();
			}
			else {
				$('#AlarmList .multipleAlarms .ping:not(.deviceSnpMultiPing),#AlarmList .multipleAlarms .clear').show();//No I18N
                 $('#AlarmList .multipleAlarms .ping:not(.deviceSnpMultiPing),#AlarmList .multipleAlarms .delete').show();//No I18N
			}

			if(ChkInput.length > 1 || OPMClient.AlarmOptionsController.freeEditionUnManageAlert)
			{
				//$('#AlarmList .multipleAlarms .ping,#AlarmList .multipleAlarms .traceRoute').addClass('disabled'); //No I18N
				$('#AlarmList .multipleAlarms .ping,#AlarmList .multipleAlarms .traceRoute').hide();
				OPMClient.AlarmOptionsController.set('isMultipleAlarmSelected',true);//No I18N
				setTimeout(function(){
                 	if(window.OPM.isOPM && ChkInput.length > 1){
                         var selr = $('#opm_Alarms').jqGrid('getGridParam','selarrrow');//No I18N
                         var deviceNameList= [];
                         for(var i=0;i<selr.length;i++)
                         {
                             deviceNameList.push($('#opm_Alarms').jqGrid("getCell", selr[i],'deviceName'));//No I18N
                         }
                         deviceNameList = removeDuplicatesInArray(deviceNameList);
                         if(deviceNameList.length===1){
                             $('#AlarmList .multipleAlarms .ping.opmSplActions').show();
                             $('#AlarmList .multipleAlarms .ping.deviceSnpMultiPing').hide();//No I18N
                         }else{
                             $('#AlarmList .multipleAlarms .ping.opmSplActions').hide();
                     		$('#AlarmList .multipleAlarms .ping.deviceSnpMultiPing').show();//No I18N
                 		}
                    }
                },100);
				/*if(OPMClient.AlarmDetailsController.isWebAlarm && window.OPM.isAuthorized)
				{
					$('.deviceslideActionBtn').show();
				}else{
					$('.deviceslideActionBtn').hide();
				}*/

				$('.deviceslideActionBtn').show();
			}
			else
			{
				//$('#AlarmList .multipleAlarms .ping,#AlarmList .multipleAlarms .traceRoute').removeClass('disabled'); 
				var selectedRow = $('#opm_Alarms tr > td:first-child input[type=checkbox]:checked').closest("tr")[0].id; //NO I18N
				eventType = $("#opm_Alarms").jqGrid("getCell", selectedRow, "eventtype");
				category = $("#opm_Alarms").jqGrid("getCell", selectedRow, "category");
				var alarmCode = $("#opm_Alarms").jqGrid("getCell", selectedRow, "alarmcode");
				var alarmEntity = $("#opm_Alarms").jqGrid("getCell", selectedRow, "entity") || '';
				if(["NFA_TRAFFIC", "SelfMonitoring Alarm","LAMAIntegration"].contains(eventType) || category == "APM" || category == "Probe" || category == "Correlated Alarms" || alarmEntity.startsWith('WMISchdulerRefresh') || alarmEntity.startsWith('DatapollThreadBlocked')){ //NO I18N
					$('#AlarmList .multipleAlarms .ping,#AlarmList .multipleAlarms .traceRoute').hide(); //NO I18N
				}else{
                    	if(selectedRow!==undefined && $('#opm_Alarms').jqGrid("getCell",selectedRow,"category")==="Group")//No I18N
                    	{
                    		$('#AlarmList .multipleAlarms .ping:not(.deviceSnpMultiPing),#AlarmList .multipleAlarms .traceRoute').hide();//No I18N
                    	}else if(selectedRow!==undefined && (OPMClient.AlarmDetailsController.sdwanChildEventCodes.contains(alarmCode) || OPMClient.AlarmDetailsController.sdwanChildEventCodes.contains(eventType)) || $('#opm_Alarms').jqGrid("getCell",selectedRow,"category")==="RemoteCollector"){//NO I18N
							$('#AlarmList .multipleAlarms .ping:not(.deviceSnpMultiPing),#AlarmList .multipleAlarms .traceRoute').hide();//No I18N
						}
						else{
                    		$('#AlarmList .multipleAlarms .ping:not(.deviceSnpMultiPing),#AlarmList .multipleAlarms .traceRoute').show();//No I18N
                    	} 
				}

				if(window.OPM.isAuthorized){	
					$('.deviceslideActionBtn').show();
				}
			}
			
			if ("FOSSelfMonitor" === alarmCategory || ("SelfMonitoring" === alarmCategory && eventType == "SelfMonitoring Alarm") || "Data Collection" === alarmCategory || eventType == "Device Count Exceeded" || "External Object" == alarmCategory) {
				$('#AlarmList .multipleAlarms .ping,#AlarmList .multipleAlarms .traceRoute').hide();
				OPMClient.AlarmOptionsController.set('isMultipleAlarmSelected',true);//No I18N
			}
		}
}

function AlarmListSortA2ZnZ2A(){
	//alarm list header sort dropdown

	opm_toggleClickAction('.AETIDFilDropDown', //No I18n
		function(){
			$('.AETIDFilDropDown').addClass('active').parent().find('ul').css({display:'block'}).animate({opacity:'1',top:'35px'},300);//No I18N
		},
		function(){
			$('.AETIDFilDropDown').removeClass('active').parent().find('ul').css({display:'none',opacity:'0',top:'0'});//No I18N
		}
	);

	//alarm list sort
	$('#AlarmList .AETIDFilDropDownList li').off('click');//No I18N
	$('#AlarmList .AETIDFilDropDownList li').click(function(){
		if(!$(this).hasClass('header')){
			$(this).parent().find('li').removeClass('active');
			$(this).addClass('active');
			$(this).parent().find('li:not(".active")').find('.sortAscDec').removeClass('sortAsc sortDec');
			 if($(this).find('.sortAscDec').hasClass('sortAsc')){
			 	$(this).find('.sortAscDec').removeClass('sortAsc').addClass('sortDec');
			 }else if($(this).find('.sortAscDec').hasClass('sortDec')){
			 	$(this).find('.sortAscDec').removeClass('sortDec').addClass('sortAsc');
			 }else{
			 	$(this).find('.sortAscDec').removeClass('sortDec').addClass('sortAsc');
			 }
			Sort=$('#AlarmList .ui-jqgrid-htable');
			if($(this).hasClass('SortMessage')){
				$(Sort).find('th:nth-child(3) div').click();
			}else if($(this).hasClass('SortSource')){
				$(Sort).find('th:nth-child(4) div').click();
			}else if($(this).hasClass('SortCategory')){
				var categoryNum = '5';
				if(OPMClient.ApplicationController.isCentralServer){
					categoryNum = '6';
				}
				$(Sort).find('th:nth-child('+categoryNum+') div').click();
			}else if($(this).hasClass('SortTechnician')){
				var technicianNum = '6';
				if(OPMClient.ApplicationController.isCentralServer){
					technicianNum = '7';
				}
				$(Sort).find('th:nth-child('+technicianNum+') div').click();
			}else if($(this).hasClass('SortSeverity')){
				$(Sort).find('th:nth-child(2) div').click();
			}else if($(this).hasClass('SortTime')){
				var sortTimeNum = '14';
				if(OPMClient.ApplicationController.isCentralServer){
					sortTimeNum = '13';
				}
				$(Sort).find('th:nth-child('+sortTimeNum+') div').click();
			}
		}
	});

	//alarm list sort a2z & z2a
	$('#AlarmList .AETIDFilSort').off('click');//No I18N
	$('#AlarmList .AETIDFilSort').click(function(){
		$('#AlarmList .AETIDFilDropDownList li.active').click();
	});
}

