function numberConvertToText(n) {
	if(window.OPM.currentView.name.indexOf("Alarms.Alarm")!==-1 && !$('.alarmInventoryFilterToggle').hasClass('active'))//No I18N
    {
         return n+"";
    }else{
	    with (Math) {
	        var base = floor(log(abs(n))/log(1000));
	        var suffix = 'kmb'[base-1];//No I18N
	        return suffix ? String(n/pow(1000,base)).substring(0,4)+suffix : ''+n;
	    }
	}
}


function opm_setLabels(id,count,label)
{
	label = escapeHTML(label);
	var parentEl = $("#"+id).parent().find('.donutTextDiv');
	if($("#"+id).data().nodata)
	{
		parentEl.find("#donutCount").html(0);	//No I18N
	}
	else
	{
		OPMClient.AlarmDetailsController.actualCount = count;
		if(id==="MainSeverityChart-A") {
			count = numberConvertToText(count);
			if(count!==undefined && (count.indexOf("k")!=-1)) {//No I18N
                OPMClient.AlarmDetailsController.modifiedCount = parseInt(count)+"k"; //No I18N
			} else {
				OPMClient.AlarmDetailsController.modifiedCount = count;
			}
			if($('.alarmInventoryFilterToggle').hasClass('active')){
				parentEl.find("#donutCount").text(OPMClient.AlarmDetailsController.modifiedCount); //No I18N
			} else {
				parentEl.find("#donutCount").text(OPMClient.AlarmDetailsController.actualCount);
			}
			if($('#opmInventorySideBarContent').hasClass('alarmInventoryFilterToggleActive')) {
				$("#"+id).attr("title",label);
			} else {
				$("#"+id).removeAttr('title');//No I18N
			}
		} else {
			parentEl.find("#donutCount").html(count);
		}
	}
	if(interfaceMainFilter.indexOf(label) >= 0){
		var indNum=interfaceMainFilter.indexOf(label);
		parentEl.find("#donutText").html(interfaceI18NMainFilter[indNum]);
	}else{
		if($('#opmInventorySideBarContent').hasClass('alarmInventoryFilterToggleActive')) {
			$("#"+id).attr("title",label);
		} else {
			$("#"+id).removeAttr('title');//No I18N
		}
		parentEl.find("#donutText").html(label);
	}

}
function opm_objectFindByKey(array, key, value) {
    for (var i = 0; i < array.length; i++) {
        if (array[i][key] === value) {
            return i;
        }
    }
    return null;
}

