function loadLiveChat()
{
	if(window.OPM.allowZiaEnabledLiveChat) {
		var response = opm_ajaxGetResponse(window.OPM.apiUrlPattern + "/zia/getUserZiaPreferences"); //No I18n
		if (response && response.allowZiaEnabledLiveChat === "true") {
			$("#live-support__ai-enabled").prop('checked', true);
		}
		$("#live-support__ai-enabled").off('change').on('change', function() {
			var isChecked = $(this).is(':checked');
			$("#liveSupportChat").addClass("disabled-block"); //No I18n
			showMessage(opm_ajaxPostRequest(window.OPM.apiUrlPattern + "/zia/updateUserZiaPreferences", {allowZiaEnabledLiveChat: isChecked})); //No I18n
			window.OPM.allowZiaEnabledLiveChat = isChecked;
			salesIqReset();
		});
	}
	$( ".live-support" ).draggable({ containment: "body", scroll: false });
		$('.live-support__icon-minimize').on('click',function(){
		$('.live-support').addClass('live-support__minimized')
	})
	$('.live-support__icon').on('click',function(){
		$('.live-support').removeClass('live-support__minimized')
	})
	hideLiveChat();
	$zoho.salesiq.ready=function(embedinfo)
	{
		$("#opmSupportChat").show();
   		$zoho.salesiq.floatwindow.visible("hide");//No I18N
   		$zoho.salesiq.floatwindow.minimize(function()
		{
			$('body').removeClass('chatActive');//No I18N
		});
		$zoho.salesiq.floatwindow.close(function(){
			document.getElementById("zsiq_float").classList.remove("block");//No I18N
			document.getElementById("liveSupportChat").classList.remove("display-none");//No I18N
			$('body').removeClass('chatActive');//No I18N
		});
	}
}
