function getProductInfo()
{	
	var data = {};
	var installDetails = opm_ajaxGetResponse(window.OPM.apiUrlPattern + "/admin/GetSystemInformation");//No I18N
	if(installDetails !== undefined)
	{
		data.ProductType = getProductNameForVisitorInfo();
		data.Version = installDetails.opmversion;
		data.OS = installDetails.ostype;
		data.Database = installDetails.databasetype;
		if(installDetails.processorname!==undefined){data.Processor = installDetails.processorname;}
		data.RAM = installDetails.ramsize;
		if(installDetails.Load!==undefined){data.Load = installDetails.Load;}
		//data.ThreadCount = installDetails.threadcount;
	}
	var monitoringDetails = opm_ajaxGetResponse(window.OPM.apiUrlPattern + "/admin/licenseDetails?isFluidic=true");//No I18N
	if(monitoringDetails !== undefined)
	{
		if(window.OPM.isOPM)
		{
			if(window.OPM.isMSPCentral){
				if(monitoringDetails.centralizedDeviceCount !== undefined && monitoringDetails.centralizedDeviceCount !== null && monitoringDetails.centralizedDeviceCount !== "") {
					data.Devices = monitoringDetails.centralizedDeviceCount;
				}
				if(monitoringDetails.interfaceCount !== undefined && monitoringDetails.interfaceCount !== null && monitoringDetails.interfaceCount !== "") {
					data.Interfaces = monitoringDetails.interfaceCount;
				}
			}else{
				if(monitoringDetails.deviceCount !== undefined && monitoringDetails.deviceCount !== null && monitoringDetails.deviceCount !== "") {
					data.Devices = monitoringDetails.deviceCount;
				}
				if(monitoringDetails.interfaceCount !== undefined && monitoringDetails.interfaceCount !== null && monitoringDetails.interfaceCount !== "") {
					data.Interfaces = monitoringDetails.interfaceCount;
				}
				if(monitoringDetails.NetFlow && monitoringDetails.NetFlow.totalLicManaged !== undefined && monitoringDetails.NetFlow.totalLicManaged !== null && monitoringDetails.NetFlow.totalLicManaged !== "") {
					data.Netflow = monitoringDetails.NetFlow.totalLicManaged + " Interfaces";//No I18N
				}
				if(monitoringDetails.NcmDeviceCount !== undefined && monitoringDetails.NcmDeviceCount !== null && monitoringDetails.NcmDeviceCount !== "") {
					data.NCM = monitoringDetails.NcmDeviceCount + " Devices";//No I18N
				}
				if(monitoringDetails.fwaDeviceCount !== undefined && monitoringDetails.fwaDeviceCount !== null && monitoringDetails.fwaDeviceCount !== "") {
					data.FWA = monitoringDetails.fwaDeviceCount + " Firewalls";//No I18N
				}
				if(monitoringDetails.OpUtils && monitoringDetails.OpUtils.NumberOfIPs !== undefined && monitoringDetails.OpUtils.NumberOfIPs !== null && monitoringDetails.OpUtils.NumberOfIPs !== "") {
					data.IPAM = monitoringDetails.OpUtils.NumberOfIPs + " IPs";//NO I18N
				}
				if(monitoringDetails.OpUtils && monitoringDetails.OpUtils.NumberOfPorts !== undefined && monitoringDetails.OpUtils.NumberOfPorts !== null && monitoringDetails.OpUtils.NumberOfPorts !== "") {
					data.SwitchPortMapper = monitoringDetails.OpUtils.NumberOfPorts + " Ports";//NO I18N
				}
				if(monitoringDetails.IpslaCount !== undefined && monitoringDetails.IpslaCount !== null && monitoringDetails.IpslaCount !== "") {
					data.IPSLA = monitoringDetails.IpslaCount + " Monitors";//No I18N
				}
			}
		}
		else if(window.OPM.isNFA)
		{
			if(monitoringDetails.NetFlow && monitoringDetails.NetFlow.totalLicManaged !== undefined && monitoringDetails.NetFlow.totalLicManaged !== null && monitoringDetails.NetFlow.totalLicManaged !== "") {
				data.Netflow = monitoringDetails.NetFlow.totalLicManaged + " Interfaces";//No I18N
			}
			if(monitoringDetails.NcmDeviceCount !== undefined && monitoringDetails.NcmDeviceCount !== null && monitoringDetails.NcmDeviceCount !== "") {
				data.NCM = monitoringDetails.NcmDeviceCount + " Devices";//No I18N
			}
			if(monitoringDetails.IpslaCount !== undefined && monitoringDetails.IpslaCount !== null && monitoringDetails.IpslaCount !== "") {
				data.IPSLA = monitoringDetails.IpslaCount + " Monitors";//No I18N
			}
		}
		else if(window.OPM.isNCM)
		{
			if(monitoringDetails.NcmDeviceCount !== undefined && monitoringDetails.NcmDeviceCount !== null && monitoringDetails.NcmDeviceCount !== "") {
				data.NCM = monitoringDetails.NcmDeviceCount + " Devices";//No I18N
			}
		}
		else if(window.OPM.isFWA)
		{
			if(monitoringDetails.fwaDeviceCount !== undefined && monitoringDetails.fwaDeviceCount !== null && monitoringDetails.fwaDeviceCount !== "") {
				data.FWA = monitoringDetails.fwaDeviceCount + " Firewalls";//No I18N
			}
		}
		else if(window.OPM.isOPUtils)
		{
			if(monitoringDetails.OpUtils && monitoringDetails.OpUtils.NumberOfIPs !== undefined && monitoringDetails.OpUtils.NumberOfIPs !== null && monitoringDetails.OpUtils.NumberOfIPs !== "") {
				data.IPAM = monitoringDetails.OpUtils.NumberOfIPs + " IPs";//NO I18N
			}
			if(monitoringDetails.OpUtils && monitoringDetails.OpUtils.NumberOfPorts !== undefined && monitoringDetails.OpUtils.NumberOfPorts !== null && monitoringDetails.OpUtils.NumberOfPorts !== "") {
				data.SwitchPortMapper = monitoringDetails.OpUtils.NumberOfPorts + " Ports";//NO I18N
			}
		}
	}
	if(window.OPM.isZiaLiveChatAllowedEdition)
	{
		data.AllowAIBot = window.OPM.allowZiaEnabledLiveChat && $("#live-support__ai-enabled").prop('checked') ? "True" : "False"; //No I18n
	}
	$zoho.salesiq.visitor.info(data);
}

function getProductNameForVisitorInfo() {
	if(window.OPM.isOPM) {
		if(window.OPM.isRMMCentral) {
			return "Monitoring(Central)";//No I18N
		}
		else if(window.OPM.isRMMProbe) {
			return "Monitoring(Probe)";//No I18N
		}
		else if(window.OPM.isMSPCentral){
			return "OpManager MSP(Central)";//No I18N
		}else if(window.OPM.isMSPProbe){
			return "OpManager MSP(Probe)";//No I18N
		}else if(window.OPM.isCentralServer){
			return "OpManager(Central)";//No I18N
		}else if(window.OPM.isProbe){
			return "OpManager(Probe)";//No I18N
		}else if(window.OPM.isOPMPLUS){
			return "OpManager Nexus";//No I18N
		}else{
			return "OpManager";//No I18N
		}
	}
	else if(window.OPM.isNFA){
		return "NetFlow Analyzer";//No I18N
	}else if(window.OPM.isNCM){
		return "NCM";//NO I18N
	}else if(window.OPM.isFWA){
		return "Firewall Analyzer";//No I18N
	}else if(window.OPM.isOPUtils){
		return "OpUtils";//No I18N
	}else{
		return "";//No i18N
	}
}
