/********** Getting Started Code starts *************/
function showGettingStarted()
{
    if(window.OPM.isNCM && (!window.OPM.isAdministrator || window.OPM.isNCMPowerUser)) {
        return;
    }
	OPMClient.ApplicationController.set("showGettingStartedAfterPassword", false); //No I18N
	if(!OPMClient.ApplicationController.hideMandatoryDetails) {
		OPMClient.ApplicationController.set("showGettingStartedAfterPassword", true); //No I18N
		return;
	}
	if(OPMClient.ApplicationController.gettingStarted.steps===undefined || !OPMClient.ApplicationController.gettingStarted.steps.length) {
		return;
	}
	if(OPMClient.ApplicationController.gettingStarted.steps[0] != undefined && OPMClient.ApplicationController.gettingStarted.steps[0].subLinks != undefined){
		OPMClient.ApplicationController.set('getStartedSublinks',OPMClient.ApplicationController.gettingStarted.steps[0].subLinks); //No I18N

	}else{
		OPMClient.ApplicationController.set('getStartedSublinks',[]); //No I18N
	}

	if(OPMClient.ApplicationController.gettingStarted.steps[0] != undefined && OPMClient.ApplicationController.gettingStarted.steps[0].infoObj != undefined){
		OPMClient.ApplicationController.set('gettingStartedInfo',OPMClient.ApplicationController.gettingStarted.steps[0].infoObj); //No I18N

	}else{
		OPMClient.ApplicationController.set('gettingStartedInfo',{}); //No I18N

	}

	if(OPMClient.ApplicationController.isOPUtils && window.OPM.userPermissions.ipamWrite && !window.OPM.userPermissions.opuRestricted && OPMClient.ApplicationController.isWindowsOS && window.OPM.isAdministrator && (OPMClient.ApplicationController.gettingStarted.steps[0].stepDesc) === Ember.I18n.t('opu.gs.IMPORT_IP_DETAILS_Desc'))
	{
		var jsonData = opm_ajaxGetResponse(window.OPM.apiUrlPattern + '/ipam/isAllDHCPServersAssociated');//No I18N
		if(!jsonData.result.isAllServersAssociated){
			$("#opuDHCPGettingSrtMsg").show();
		}else{
			$("#opuDHCPGettingSrtMsg").hide();
		}
	}
	$('#opmGettingStarted').css({'display':'block'});//No I18N
	if(window.OPM.isOPUtils){
		$(".gettingStartedAnimateDiv").addClass("opUtils");//No I18N
	}
	if(window.OPM.currentView!==undefined && window.OPM.currentView.name==="Home.Dashboard.index"){//No I18N
		$('body').addClass('dashboardPage');//No I18N
	}
	$("#stepDesc").text((OPMClient.ApplicationController.gettingStarted.steps[0] != undefined) ? OPMClient.ApplicationController.gettingStarted.steps[0].stepDesc : '');
	$("#opmGettingStarted #innerCont .menuList li").removeClass("current");//No I18N
	$("#opmGettingStarted #innerCont .menuList li:first-child").addClass("current");//No I18N
	$("#opmGettingStarted .menuList .overEffect").css({left:'0px'});
	$("#gettingStartedIcon .starBlink").removeClass("active");//No I18N
	if(!window.OPM.isFWA){
		var incInterval;
		$("#opmGettingStarted #innerCont .menuList li").on("mouseenter focus",function(){//No I18N
			var self = $(this);
			var menuWidth = $(".opmGettingStarted .menuList li").outerWidth();
			var menuCount = $(self).prevAll("li").length;
			var MouseHoverTiming = 1;
			incInterval = setInterval(function(){
		      	MouseHoverTiming++;
		      	if(MouseHoverTiming >=1){
					$(".opmGettingStarted .menuList .overEffect").css('left',menuWidth*menuCount)
					$(".opmGettingStarted .menuList li").removeClass("current");
					$(self).addClass("current");
					var stepNo = $(self).attr("data-nav")-1;//No I18N
					if(stepNo !== undefined && OPMClient.ApplicationController.gettingStarted.steps[stepNo]!==undefined)
					{
						$("#stepDesc").text(OPMClient.ApplicationController.gettingStarted.steps[stepNo].stepDesc);//No I18N
						if((OPMClient.ApplicationController.gettingStarted.steps[stepNo].stepDesc) === Ember.I18n.t('opu.gs.IMPORT_IP_DETAILS_Desc'))
						{
							$("#opuDHCPGettingSrtMsg").show();
						}else{
							$("#opuDHCPGettingSrtMsg").hide();
						}
						if(OPMClient.ApplicationController.gettingStarted.steps[stepNo].subLinks != undefined){
							OPMClient.ApplicationController.set('getStartedSublinks',OPMClient.ApplicationController.gettingStarted.steps[stepNo].subLinks); //No I18N
						}else{
							OPMClient.ApplicationController.set('getStartedSublinks',[]); //No I18N
						}

						if(OPMClient.ApplicationController.gettingStarted.steps[stepNo].infoObj != undefined){
							OPMClient.ApplicationController.set('gettingStartedInfo',OPMClient.ApplicationController.gettingStarted.steps[stepNo].infoObj); //No I18N
						}else{
							OPMClient.ApplicationController.set('gettingStartedInfo',{}); //No I18N
						}
					}
		      	}else{
			 		clearInterval(incInterval);
		      	}
		    },200);
		}).on("mouseleave blur",function(){
			clearInterval(incInterval);
		});
	}
	$('.opmGettingStarted .menuList li p.menuTitle').removeClass('textEffect');
	$('.opmGettingStarted .menuList li p').css('font-size','19px');
	var totalGettingStartedMsg = $('.opmGettingStarted .menuList li').length;
	for(i=0;i<totalGettingStartedMsg;i++){
		var titleHeightGettingStartedMsg = $('.opmGettingStarted .menuList li:eq('+i+') p.menuTitle').height();
		if(titleHeightGettingStartedMsg > 30){
			$('.opmGettingStarted .divTableContent').addClass('twoLineTitle');
		}	
	}
	$('.opmGettingStarted .menuList li p').css('font-size','16px');
	setTimeout(function(){
		$('.opmGettingStarted .menuList li p.menuTitle').addClass('textEffect')
	},100);

	if(window.OPM.isOPM && window.OPM.isAuthorized && !window.OPM.isCustomer && !window.OPM.isOPMPLUS)
	{
		var resp = opm_ajaxGetResponse(window.OPM.apiUrlPattern + '/admin/gettingStartedInfo?queryType=stageStatus');//No I18N
    	if(resp !== undefined && resp.message !== undefined && resp.message !== ""){
	    	showAutoDiscoveryStatus(resp);
    	}
    }
}
function showTabSpecificDetails(pageURL,pageName,targetValue)
{
	 hideGettingStarted(pageURL);
	 setTimeout(function(){
	 	if(pageName==="NotificationProfile"){//No I18N
		 	$("#notificationProfileForm .NotifyProfile li[data-targetdiv='"+targetValue+"']").click();//No I18N
		}else if(pageName==="AddNOCView"){//No I18N
			addEditNocView(true,"");
		}else if(pageName==="performanceMonitors"){//No I18N
			opm_transitionToParentRoute("Settings.Monitors.SubMonitors.AddPerfMonitor",pageName);//No I18N
		}else if(pageName==="windowsServices" || pageName==="processes" || pageName==="scriptMonitors"){//No I18N
			opm_transitionToParentRoute("Settings.Monitors.SubMonitors.Add",pageName);//No I18N
		}else if(pageName==="ScheduleReports"){//No I18N
			isMailServerConfigured("Reports.Opmanager.CreateScheduleReport",Ember.I18n.t('webclient.admin.schedulereports.warning',this));//No I18N
		}else if(pageName=="AddToNCM"){//No I18N
	 		if(targetValue=="add")
	 			$("#SpecificDevice").click();
	 		else if(targetValue=="import")
	 			$("#DeviceGroup").click();
	 	}
	 },1000);
}
function hideGettingStarted(pageURL,isExternalUrl)
{
	$('body').addClass('gettingStartedCloseAnimate');//No I18N
	$("#gettingStartedIcon .starBlink").addClass("active");//No I18N
	if(window.OPM.isOPM && window.OPM.showGettingStarted){
		 if(pageURL!==undefined){
			 opmUserStats('gs_actions');//No I18N
		 }else{
			  opmUserStats('gs_close');//No I18N
		}
	}
	var rect = $('#gettingStartedIcon')[0] ? $('#gettingStartedIcon')[0].getBoundingClientRect().right : 1200;
	$('body.gettingStartedCloseAnimate .opmGettingStarted .gettingStartedAnimateDiv').css("right",window.innerWidth - rect);
	updateUIInfoMessage("GettingStarted");//No I18N
	window.OPM.showGettingStarted = false;
	setTimeout(function(){
		$('#opmGettingStarted').css({'display':'none'});//No I18N
		$('body').removeClass('gettingStartedCloseAnimate').removeClass('dashboardPage');//No I18N
		if(pageURL!==undefined && pageURL!==""){
			if(isExternalUrl) {
				window.open(pageURL,"_blank");
			}else if(window.OPM.isOPUtils && pageURL.indexOf("Inventory")!= -1){
				oputilsGSRedirect(pageURL);
			}
			else{
				if(!window.OPM.isV3ClientRestricted && (pageURL.includes('#/reports') || pageURL.includes('#/alarms'))){
					location.href = pageURL;
				}else{
				    location.href = window.OPM.apiclientUrl + pageURL;
				}
			}
		}
		$('body .opmGettingStarted .gettingStartedAnimateDiv').css("right",0);
	},500); 
	// setTimeout(function(){
	// 	$("#gettingStartedIcon .starBlink").removeClass("active");
	// },10000);
}
function modifyGettingStartedHeight()
{
	setTimeout(function(){
		var winHt = $(window).height();
		var scrollHt = $('#opmGettingStarted .divTableContent')[0].scrollHeight;//No I18N
		var divHt = (((scrollHt+100) > winHt)?(winHt-50):scrollHt+20)+((window.OPM.isNFA)?30:4);
		$('#opmGettingStarted .divTableContent,.gettingStartedAnimateDiv').css({'height':divHt+'px'});//No I18N
	},0);
}
function oputilsGSRedirect(pageURL){
	var params = pageURL.split('_')
	localStorage.removeItem("opu_mapView");//No I18N
	OPMClient.InventoryDeviceDetailsController.set('isGS',true);//No I18N
	OPMClient.InventoryDeviceDetailsController.set("subFilterType",params[0]);
	OPMClient.InventoryDeviceDetailsController.set('opuURL',params[2]);
	if(params[0]=="Subnets" || params[0]=="DHCP"){
		redirectToSnapshot('IPAMSubnetGroupSummary', 'GROUP_0',undefined,true);//No I18N
		setTimeout(function(){
			if(params[0]=="DHCP"){
				opmGlobalRoute.transitionTo('Inventory.Device.AddDHCP');//No I18N
			}else{
				opmGlobalRoute.transitionTo('Inventory.Device.AddSubnet','IPv4');//No I18N
			}
		},500);
	}else if(params[0]=="Switches"){
		if(OPMClient.InventoryDeviceDetailsController.pageName!=="SPM" || window.OPM.currentView.name!=="Inventory.Device.index"){
			redirectToSnapshot('IPAMSwitchGroup', 'SPMGROUP_0',undefined,true);//No I18N
			setTimeout(function(){
				opmGlobalRoute.transitionTo('Inventory.Device.AddSwitch');//No I18N
			},1200);
		}
		else{
			opmGlobalRoute.transitionTo('Inventory.Device.AddSwitch');//No I18N
		}
	}else{
		if(params[1]!="DHCP"){
			OPMClient.InventoryDeviceDetailsController.set('opuGSAction',params[1]);
		}else{
			OPMClient.InventoryDeviceDetailsController.set('opuGSAction',"");
		}
		if(window.OPM.currentView.name=="Inventory.List.OpUtils.Sub.Configure.index" || window.OPM.currentView.name=="Inventory.List.OpUtils.Sub.index"){
			location.href= window.OPM.apiclientUrl+params[2];
			opm_emberViewRerender("Inventory.List.OpUtils.Sub.Configure");//No I18N
		}else{
			opmGlobalRoute.transitionTo("Inventory.List.OpUtils.Sub",params[0]);
		}
	}
}

