function tabCustomizationActions()
{
	initializeMainMenuScroll();
	initializeSubMenuScroll();
}
function initializeMainMenuScroll()
{
	$("#mainNavSort").mCustomScrollbar("destroy");//No I18N
	$("#mainNavSort").mCustomScrollbar({//No I18N
		axis:"x",//No I18N
		scrollButtons:{enable:true},
		theme:"light-thick",//No I18N
		scrollbarPosition:"outside",//No I18N
		mouseWheelPixels:50,
		scrollInertia:0
	});
}
function initializeSubMenuScroll()
{
	$("#subNavSort").mCustomScrollbar("destroy");//No I18N
	$("#subNavSort").mCustomScrollbar({//No I18N
		axis:"x",//No I18N
		scrollButtons:{enable:true},
		theme:"light-thick",//No I18N
		scrollbarPosition:"outside",//No I18N
		mouseWheelPixels:50,
		scrollInertia:0
	});
}
function initializeTabCustomizeActions()
{
	$('#mainNavSortList').on('click','td',function(e){//No I18N
		$(this).closest('tr').find('td').removeClass('active');//No I18N
		$(this).addClass('active');//No I18N
		if(e.target!==undefined)
		{
			var parentEle = $(e.target).closest('td').find('div:first-child');//No I18N
			if($(e.target).hasClass('editIcon'))//No I18N
			{
				var tabInfo = {};
				tabInfo.tabIdentifier = parentEle.data('identifier');//No I18N
				tabInfo.primaryTab = true;
				tabInfo.isVisible = !parentEle.hasClass("disabled");//No I18N
				OPMClient.MenuController.set("tabInfo",tabInfo);//No I18N
			}
			else if($(e.target).hasClass('closeIcon'))//No I18N
			{
				OPMClient.MenuController.mainTabDetails[parentEle.data('identifier')].isVisible = false;//No I18N
				parentEle.hide();
			}
			else
			{
				if($(parentEle).data('nosecondarymenu')){//No I18N
					$('html').addClass("noSubMenu");//No I18N
				}else{
					$('html').removeClass("noSubMenu");//No I18N
				}				
				var identifier = $(parentEle).data('identifier');//No I18N
				OPMClient.MenuController.set("customizeSecondaryMenus",OPMClient.MenuController.mainTabDetails[identifier].subtabs);//No I18N
				initializeSubMenuScroll();	
			}
		}
	});
	$('#subNavSortList').on('click','td',function(e){//No I18N
		$(this).closest('tr').find('td').removeClass('active');//No I18N
		$(this).addClass('active');//No I18N
		if(e.target!==undefined)
		{
			var parentEle = $(e.target).closest('td').find('div:first-child');//No I18N
			if($(e.target).hasClass('editIcon') && !parentEle.hasClass("disabledBlock"))//No I18N
			{
				var tabInfo = {};
				tabInfo.tabIdentifier = parentEle.data('identifier');//No I18N
				tabInfo.parentIdentifier = parentEle.data('parentidentifier');//No I18N
				tabInfo.secLinkName = parentEle.data('seclinkname');//No I18N
				tabInfo.secondaryTab = true;
				tabInfo.isVisible = !$(parentEle).hasClass("disabled");
				OPMClient.MenuController.set("tabInfo",tabInfo);//No I18N
			}
			else if($(e.target).hasClass('closeIcon')  && !parentEle.hasClass("disabledBlock"))//No I18N
			{
				var currTab = OPMClient.MenuController[parentEle.data('seclinkname')];//No I18N
				var tempTab = getSelectedSubTab(currTab,parentEle.data('identifier'));//No I18N
				if(!OPMClient.MenuController.mainTabDetails[tempTab.parentIdentifier].isCustom)
				{
					var subTabCount = $("#subNavSortList td > div").not(".disabled").length;//No I18N
					if(subTabCount<2){
						opm_infoMsgs("infoMsg",Ember.I18n.t("webclient.subtab.miniumtabcount.msg",this));//No I18N
						return;
					}
				}
				$(parentEle).addClass("disabled");//No I18N
				tempTab.isVisible = false;//No I18N
				parentEle.hide();
			}
		}
	});
	$('#mainNavSortList').sortable({//No I18N
		update: function(event,ui){
			changePrimaryTabsPosition();
		}
	});
	$('#subNavSortList').sortable({//No I18N
		update: function(event,ui){
			changeSecondaryTabsPosition();
		}
	});
	$("#mainNavSortList > td:first-child").addClass("active").trigger('click');//No I18N
}
function changePrimaryTabsPosition()
{
	var mainEle = $("#mainNavSortList > td > div");//No I18N
	for(var i=0;i<mainEle.length;i++)
	{
		var currEle = mainEle[i];
		var identifier = currEle.getAttribute('data-identifier');//No I18N
		currEle.setAttribute("data-position",(i+1));//No I18N
		OPMClient.MenuController.mainTabDetails[identifier].tab_position = i+1;
	}
}
function changeSecondaryTabsPosition()
{
	var mainEle = $("#subNavSortList > td > div");//No I18N
	for(var i=0;i<mainEle.length;i++)
	{
		var currEle = mainEle[i];
		var parentIdentifier = currEle.getAttribute('data-parentidentifier');//No I18N
		var identifier = currEle.getAttribute('data-identifier');//No I18N
		currEle.setAttribute("data-position",(i+1));//No I18N
		if(OPMClient.MenuController.mainTabDetails[parentIdentifier] !== undefined) {
			var tempTab = getSelectedSubTab(OPMClient.MenuController.mainTabDetails[parentIdentifier].subtabs,identifier);
			tempTab.tab_position = i+1;
		}
	}
}
function getSelectedSubTab(currTab,tabIdentifier)
{
	var tempTab = {};
	for(var i=0;i<currTab.length;i++)
	{
		tempTab = currTab[i];
		if(tempTab.tabIdentifier===tabIdentifier){
			return tempTab;
		}
	}
}
function setTabIdentifier(displayName)
{
	displayName = displayName.replace(/\s/g,'');
	displayName = "custom_"+displayName+"_"+ Date.now();//No I18N
	return displayName;
}
function saveTabDetails()
{
	changePrimaryTabsPosition();
	var resultArr = [];
	var atleastOneTabPresent = false;
	var atleastOneSubTabPresent = true;
	var tabDetailsLength = OPMClient.ApplicationController.tabDetails.length;
	for(var i=0;i<tabDetailsLength;i++)
	{
		var currTab = OPMClient.ApplicationController.tabDetails[i];
		var tempTab = {};
		tempTab.displayName = currTab.displayName.trim();
		tempTab.isVisible = currTab.isVisible;
		tempTab.is_default = currTab.is_default;
		tempTab.tabIdentifier = currTab.tabIdentifier;
		tempTab.tab_position = currTab.tab_position;
		if(tempTab.displayName.length > 50) {
			opm_infoMsgs("errorMsg", Ember.I18n.t("webclient.custom.maxchars", {fieldName: Ember.I18n.t("webclient.customtab"), maxLength: 50})); //No I18n
			return;
		}
		if(!currTab.isNewTab){
			tempTab.tabID = currTab.tabID;
			tempTab.defaultTabID = currTab.defaultTabID;
		}
		tempTab.linktype = currTab.linktype;
		tempTab.tab_link = currTab.tab_link;
		tempTab.subtabs = getSubTabDetails(currTab.subtabs);
		if(tempTab.subtabs === -1) {
			return;
		}
		if(tempTab.is_default || tempTab.isVisible){
			resultArr.push(tempTab);
			if(tempTab.isVisible){
				atleastOneTabPresent=true;
				//Explicit condition due to mobile app promotion permission in General Settings 
				if(!window.OPM.isNCM && tempTab.subtabs.length == 0 && tempTab.tabIdentifier == "Settings") {
					break;
				}
				if(!window.OPM.isNCM && tempTab.is_default && currTab.noSecondaryMenu===undefined){
					atleastOneSubTabPresent = checkAtleastOneSubTabPresent(tempTab.subtabs);
					if(!atleastOneSubTabPresent){
						break;
					}
				}
			}
		}
	}
	if(!window.OPM.isNCM && !atleastOneSubTabPresent){
		opm_infoMsgs("infoMsg",Ember.I18n.t("webclient.subtab.miniumtabcount.msg",this));//No I18N
		return;
	}
	if(!atleastOneTabPresent){
		opm_infoMsgs("infoMsg",Ember.I18n.t("webclient.tab.miniumtabcount.msg",this));//No I18N
		return;
	}
	$.ajax({
		url: window.OPM.apiUrlPattern+"/admin/updateTabs",//No I18N
		data: {"tabDetails":JSON.stringify(resultArr)},//No I18N
		type: 'POST',//No I18N
		dataType: 'json', //No I18n
		success: function(response){
			if(response.error!==undefined && response.error.message!==undefined){
				opm_infoMsgs("errorMsg",response.error.message);//No I18N
			}else if(response.result!==undefined && response.result.message!==undefined){
				opm_infoMsgs("successMsg",Ember.I18n.t(response.result.message,this));//No I18N
				setTimeout(function () {
					location.reload();
				}, 400);
				
			}
		}
	});
}
function getSubTabDetails(subtabsArr)
{
	var resultSubObj = [];
	var subtabsArrLength = subtabsArr.length;
	for(var j=0;j<subtabsArrLength;j++)
	{
		var subTab = subtabsArr[j];
		if(!subTab.isMenuHoverOption)
		{
			var tempTab = {};
			tempTab.displayName = subTab.displayName.trim();
			if(tempTab.displayName.length > 50) {
				opm_infoMsgs("errorMsg", Ember.I18n.t("webclient.custom.maxchars", {fieldName: Ember.I18n.t("webclient.customtab"), maxLength: 50})); //No I18n
				return -1;
			}
			tempTab.isVisible = subTab.isVisible;
			tempTab.is_default = subTab.is_default;
			tempTab.tabIdentifier = subTab.tabIdentifier;
			tempTab.tab_position = subTab.tab_position;
			if(!subTab.isNewTab){
				tempTab.tabID = subTab.tabID;
				tempTab.defaultTabID = subTab.defaultTabID;
			}
			tempTab.linktype = subTab.linktype;
			tempTab.tab_link = subTab.tab_link;
			tempTab.parentTabID = subTab.parentTabID;
			if((tempTab.is_default || tempTab.isVisible) && tempTab.tab_position != undefined){
				resultSubObj.pushObject(tempTab);
			}			
		}
	}
	return resultSubObj;
}
function redirectMainCustomMenu(tabIdentifier)
{
	if(tabIdentifier!==undefined && tabIdentifier!=="")
	{
		OPMClient.ApplicationController.set("embedTabDetails",{});//No I18N
		var tabInfo = OPMClient.MenuController.mainTabDetails[tabIdentifier];
		if(tabInfo.linktype==="url"){//No I18N
			window.open(tabInfo.tab_link);
		}else if(tabInfo.linktype==="embed"){//No I18N
			// Ember.set(OPMClient.ApplicationController,"embedTabDetails",{});//No I18N
			// renderEmbedTab(tabInfo);
			opmGlobalRoute.transitionTo('CustomMenu', tabIdentifier); //No I18N
		}
	}
}
function redirectSecondaryCustomMenu(secLinkName,tabIdentifier)
{
	var currTab = OPMClient.MenuController[secLinkName];
	var tempTab = getSelectedSubTab(currTab,tabIdentifier);
	if(tempTab.linktype==="url"){//No I18N
		if(tempTab.tab_link.startsWith(location.origin) && tempTab.tab_link.includes("apiclient/ember/index.jsp")) {
			location.href = tempTab.tab_link;
			return ;
		} else {
			window.open(tempTab.tab_link);
		}
	}else if(tempTab.linktype==="embed"){//No I18N
		// Ember.set(OPMClient.ApplicationController,"embedTabDetails",{});//No I18N
		// renderEmbedTab(tempTab);
		opmGlobalRoute.transitionTo('CustomMenu', tabIdentifier); //No I18N
	}
}
