function isEmptyObject(obj) {
    for(var key in obj) {
        if(obj.hasOwnProperty(key))
            return false;
    }
    return true;
}
function initializeMenuHoverAction(ele1,ele2)
{
	$(ele1).on('mouseenter',ele2,function(t1){//No I18N
	    var self = $(this);
	    clearTimeout(self.data('hoverTimer'));//No I18N
	    var timer = setTimeout(function(t1){
			if($(self).hasClass('open')){//No I18N
            	return;
        	}else{
            	$(self).addClass('open');//No I18N
            	$(self).siblings().removeClass('open');//No I18N
        	}
    	},200);
    	self.data('hoverTimer',timer);//No I18N
	}).on('mouseleave',ele2,function(t2){
    	var self = $(this);
    	clearTimeout(self.data('hoverTimer'));//No I18N
    	var timer = setTimeout(function(t2){
        	if (!$(self).hasClass('open')) {//No I18N
            	return;
        	} else {
            	$(self).removeClass('open');//No I18N
        	}
    	},300);
    	self.data('hoverTimer',timer);//No I18N
	})
	.on('focus', ele2, function() {
        var self = $(this);
	    clearTimeout(self.data('hoverTimer'));//No I18N
	    var timer = setTimeout(function(t1){
			if($(self).hasClass('open')){//No I18N
            	return;
        	}else{
            	$(self).addClass('open');//No I18N
            	$(self).siblings().removeClass('open');//No I18N
        	}
    	},200);
    	self.data('hoverTimer',timer);//No I18N
    })
    .on('blur', ele2, function() {
        var self = $(this);
    	clearTimeout(self.data('hoverTimer'));//No I18N
    	var timer = setTimeout(function(t2){
        	if (!$(self).hasClass('open')) {//No I18N
            	return;
        	} else {
            	$(self).removeClass('open');//No I18N
        	}
    	},300);
    	self.data('hoverTimer',timer);//No I18N
    }).on('keydown', function(event) {
    	if (event.key === 'Enter' || event.keyCode === 13) {
    		var parentElement = $(event.target).parent().parent().parent();
			var parentElement1 = $(event.target).parent().parent().parent().parent().parent().parent().parent();
    		if (parentElement.hasClass('open')) {//No I18N
    			parentElement.removeClass('open');//No I18N
    		} else if(parentElement1.hasClass('open')) {//No I18N
				parentElement1.removeClass('open');//No I18N
			}
    	}
    });
}
function getSubTabHeaderValue(primaryTab,tabIdentifier,key)
{
	var value;
	var subTabsLength = 0;
	if(OPMClient.MenuController.mainTabDetails[primaryTab]!==undefined){
		subTabsLength = OPMClient.MenuController.mainTabDetails[primaryTab].subtabs.length;
	}
	for(var i=0;i<subTabsLength;i++)
	{
		if(tabIdentifier === OPMClient.MenuController.mainTabDetails[primaryTab].subtabs[i].tabIdentifier){
			value = OPMClient.MenuController.mainTabDetails[primaryTab].subtabs[i][key];
			break;
		}
	}
	return value;
}
function redirectToFirstMainMenuTab()
{
	var index = getFirstShownTabIndex();
	if(OPMClient.ApplicationController.tabDetails!==undefined && OPMClient.ApplicationController.tabDetails.length!=0){
		if(OPMClient.ApplicationController.tabDetails[index].hrefLink!==undefined){
			location.href= OPMClient.ApplicationController.tabDetails[index].hrefLink;
		}else if(OPMClient.ApplicationController.tabDetails[index].route!==undefined){
			if(OPMClient.ApplicationController.tabDetails[index].path!==undefined){
				opmGlobalRoute.transitionTo(OPMClient.ApplicationController.tabDetails[index].route,OPMClient.ApplicationController.tabDetails[index].path);
			}else{
				opmGlobalRoute.transitionTo(OPMClient.ApplicationController.tabDetails[index].route);
			}
		}else if(OPMClient.ApplicationController.tabDetails[index].clickFn!==undefined || (OPMClient.ApplicationController.tabDetails[index].isCustom && OPMClient.ApplicationController.tabDetails[index].linktype === "embed")){
			var clickFn = new Function(OPMClient.ApplicationController.tabDetails[index].clickFn);
			clickFn();
			$("#MainNav .NavUl > li:first-child").addClass("active");//No I18N
		}else if(OPMClient.ApplicationController.tabDetails[index].subPath!==undefined){
			$("#MainNav .NavUl > li:first-child").addClass("active");//No I18N
			location.href = setMainTabPath(OPMClient.ApplicationController.tabDetails[index].subPath,true);
		}
	}else{
		opmGlobalRoute.transitionTo('Home.Index'); //No I18N
	}
}
function getFirstShownTabIndex()
{
	var index = 0;
	for(var i=0;i<OPMClient.ApplicationController.tabDetails.length;i++)
	{
		if(OPMClient.ApplicationController.tabDetails[i].isVisible){
			index = i;
			break;
		}
	}
	return index;
}
