function checkAtleastOneSubTabPresent(subtabsArr)
{
	var tabPresent = false;
	for(var i=0;i<subtabsArr.length;i++)
	{
		if(subtabsArr[i].isVisible){
			tabPresent = true;
			if(subtabsArr[i].tab_position == undefined) {
				subtabsArr.splice(i--, 1);
			} else {
				break;
			}
		}
	}
	return tabPresent;
}
