function onScrollTopBandHide(){
	if(window.OPM.isOPM && !window.OPM.isRMMEdition){
		$('#main').on('DOMMouseScroll mousewheel','.scrollHideMenu',function ( event ) {//No I18N
			var navPosition = $('#nav').position();//No I18N
			if($(this).scrollTop() > navPosition.top){ 
				$('html').css({//No I18N
					'height':'-webkit-calc(100% + ' + navPosition.top + 'px)',//No I18N
					'height':'calc(100% + ' + navPosition.top + 'px)',//No I18N
					'-webkit-transform':'translateY(-' + navPosition.top + 'px)',//No I18N
					'-ms-transform':'translateY(-' + navPosition.top + 'px)',//No I18N
					'transform':'translateY(-' + navPosition.top + 'px)'//No I18N
				});
				$('html').addClass('onScrollTopBandHide');//No I18N
				if(!$('#fullScreenToggleIcon').hasClass('active')) {
					$('#fullScreenToggleIcon').addClass('active');//No I18N
				}
		    }else{
		    	if($(this).scrollTop() < navPosition.top){
		    		resetScrollEvent();
		    	}
		  	}
		});
	}
}
function resetScrollEvent(){
	if(window.OPM.isOPM){
		$('html').css({//No I18N
			'height':'100%',//No I18N
			'-webkit-transform':'translateY(0px)',//No I18N
			'-ms-transform':'translateY(0px)',//No I18N
			'transform':'translateY(0px)'//No I18N
		});
		$('html').removeClass('onScrollTopBandHide');//No I18N
		if($('#fullScreenToggleIcon').hasClass('active')) {
			$('#fullScreenToggleIcon').removeClass('active');//No I18N
		}
	}
}
function resetScrollEventTransformNone(){
	if(window.OPM.isOPM){
		$('html').css({//No I18N
			'height':'100%',//No I18N
			'-webkit-transform':'none',//No I18N
			'-ms-transform':'none',//No I18N
			'transform':'none'//No I18N
		});
		$('html').removeClass('onScrollTopBandHide');//No I18N
	}
}

