function showPopover(){
	$('tbody').off('click').on('click', '[target="popover"]', function (event) {
		var offset = $(this).offset();
		var height = $(this).height();
		var popoverHeight = $('.popover').height();
		var popoverWidth = $('.popover').width();
		event.stopPropagation();
		// Checking top position
		if ((offset.top + height) < (window.innerHeight - popoverHeight)) {
			$('.popover').css({ 'top': (offset.top + height + 10)}).show();
		} else {
			$('.popover').css({ 'top': (offset.top - popoverHeight - 10)}).show();
		}
		// Checking Left Right position
		if (event.pageX - offset.left+ popoverWidth < window.innerWidth) {
			if(event.pageX > popoverWidth/2){
				$('.popover').css({'left': ((event.pageX) - ((popoverWidth/2) - 30)),'right': 'unset'});//No I18N
			} else {
				$('.popover').css({'left': 10,'right': 'unset'})
			}
		} else{
			$('.popover').css({'left': 'unset','right': 10})
        }
        $(document).on('mouseup',function (e) {
            var container = $('.popover');
            // If the target of the click isn't the container
            if (!container.is(e.target) && container.has(e.target).length === 0) {
                container.hide();
                Ember.set('OPMClient.ApplicationController.popOverAttributes', {});//No I18N
                $(document).off('mouseup');
            }
        });
	});
}

