function mandatoryStepChange(self,prevStep,nextStep) {
 	var config = self.get('controller.ConfigurationSteps');
	$('.mandateSteps').hide();
	config = config.map(function(obj) {
		obj.isActive = false;
		return obj.id == (prevStep) ? (delete obj.configStatus1, delete obj.statusClass, $.extend({}, obj, {configStatus1: obj.configStatus2,statusClass:'securityStatus__configured'})) : obj.id == (nextStep) ?  ($.extend({}, obj, {isActive:true})) : obj;
		});
	$('#'+nextStep+'Content').show();
	self.set('controller.ConfigurationSteps',config);// No I18N
}

