function checkIfAnyPopupShown()
{
	var isPopupEnabled = false;
	
	//Getting started page
	if($('#opmGettingStarted').is(':visible') || $('#EEGettingStarted').is(':visible')){//No I18n
		isPopupEnabled = true;
	}

	//Tour mobile app ad popup
	if($('#productMobileAppAd').is(':visible')){//No I18n
		isPopupEnabled = true;
	}

	//Product expire popups
	if($('#productTrialExpiresInfo').is(':visible') || $('#productExpiresInfo').is(':visible')){//No I18n
		isPopupEnabled = true;
	}

	//Upgrade popups
	if($('#APMUpgradeInfo').is(':visible') || $('#PopUpCheckbox').prop('checked') || $('#SDPV3UpdateAlert').is(':visible')){//No I18n
		isPopupEnabled = true;
	}

	//Password change Alert
	if($('#scpPwdDiv').is(':visible') || $('#passwordChange').is(':visible') || $('#pswdchange').is(':visible') || $('#passwordChangeAlert').is(':visible')){//No I18n
		isPopupEnabled = true;
	}
	//License Popup
	if(window.OPM.isLicenseExceeded || window.OPM.showLicensePopup){
		isPopupEnabled = true;
	}

	//NFADE Collector Alert
	if($("#nfaDEInfoMsgDiv").is(':visible')){//No I18n
		isPopupEnabled = true;
	}
	//General handler for popup
	if($('body').hasClass('ui-dialog-style2')){//No I18n
		isPopupEnabled = true;
	}
	return isPopupEnabled;
}
function addNotes() {
	OPMClient.AlarmActionsController.opm_alarmsAddnote(OPMClient.AlarmDetailsController.currentAlarmEntity,false);
}
function addAlarmNotesFromGenAI(elementId, element) {
	var alarmId = OPMClient.AlarmDetailsController.currentAlarmEntity;
	var url = window.OPM.apiUrlPattern + '/alarm/addNotes?isFluidic=true';//No I18N
	var notesElement = document.getElementById(elementId);
	if(elementId && notesElement) {
		var resp = opm_ajaxPostRequest(url, {
			notes: notesElement.textContent,
			alarmId: alarmId
		});
		
		showMessage(resp); 
		
		if(element) {
			// element.classList.add("disabledBlock"); // No I18N
			element.innerHTML = '<svg aria-hidden="true" width="18" height="18"><use xlink:href="/apiclient/fluidicv3/itom/@zoho/itom-ui-library/itom-icons/sprite-icons.svg#check-circle-fill"></use></svg>' + Ember.I18n.t("webclient.genai.addAlarmNotesAdded"); // No I18N
			element.setAttribute("class", "text-primary bold flex flex-middle-align gap-xxs"); // No I18N
			element.removeAttribute("onclick") // No I18N
		}

		if($('#opm_AlarmNotes').length) { // No I18N
			getAnnotation()
		}
	}
}
