function showCustomDynamicPopup(prop) {
	var customDialogID = prop.popupId;
	$.each(customDialogList, function (key,value) {
		if(value.dialogID == customDialogID) {
			value.viewObj = prop;
			OPMClient.ApplicationController.set("itomDialogDetails",value);//No I18n
			return false;
		}
	});
}
function showCustomDialogPopup(dialogList) { 
	$.each(dialogList, function (key,value) {
		if(value.isHide != undefined && !value.isHide) {
			OPMClient.ApplicationController.set("itomDialogDetails",value);//No I18n
			dialogList.splice(key,1);
			OPMClient.ApplicationController.itomDialogDetails.closeFunctionCallBack = function(){
				Ember.run.schedule('afterRender', function() { //No I18n
					showCustomDialogPopup(dialogList);
				});
			}
			return false;
		}
	});
}
function topBandSwitch() {
		var count = 1;
		var showTopBand, hideTopBand;
		$('.centralProbStatusInfo').hide();
		var timeOut = setInterval(function() {
			if(OPMClient.ApplicationController.restartInMinute) {
				clearInterval(timeOut);
				$('.centralProbStatusInfo').fadeOut(800,function(){
					$('.restartTimerTopBand').fadeIn(800);
				});
				return;
			}
			if(count%2 == 0) {
				showTopBand = "restartTimerTopBand";//No I18n
				hideTopBand = "centralProbStatusInfo";//No I18n
			} else {
				showTopBand = "centralProbStatusInfo";//No I18n
				hideTopBand = "restartTimerTopBand";//No I18n
			}
			if(!$('.'+hideTopBand).is(':hover')) {
				$('.'+hideTopBand).fadeOut(800,function(){
					$('.'+showTopBand).fadeIn(800);
				});
				count++;
			}
		}, 10000);
	}

