function setAutomaticRefreshOptions() {
	if(String(window.OPM.autoRefresh) === "-1" || String(window.OPM.autoRefresh) === "")
	{
		$('input[name="autoRefreshBtn"][data-value="sessiontimeout"]').prop('checked',true);//No I18N
		$("#sessionTimeoutVal").val(window.OPM.sessiontimeout).select2();
		$('#autoRefreshInterval').val("10");
	}
	else
	{
		$('input[name="autoRefreshBtn"][data-value="autorefresh"]').prop('checked',true);//No I18N
		$('#autoRefreshInterval').val(window.OPM.autoRefresh);
		$("#sessionTimeoutVal").val("-1").select2();
	}
	$('input[name="autoRefreshBtn"]:checked').trigger("change");
}


function changeValue(delta) {
	var input = document.getElementById('numberInput');
	var value = parseInt(input.value, 10) || 16;
	var min = parseInt(input.min, 10) || 16;
	var max = parseInt(input.max, 10) || 24;
	value += delta;
	if (value < min) value = min;
	if (value > max) value = max;
	input.value = value;
}

